  FROM "legacy_object_live"
 WHERE "_key" = ANY($1::TEXT[])`,
		values: [keys],
	});

	const invalid = res.rows.filter(r => r.type !== type);

	if (invalid.length) {
		const parts = invalid.map(r => `${JSON.stringify(r._key)} is ${r.type}`);
